// Construct the lookup GID from the stored numeric variant ID, then confirm availability.
// The response's variantData.productVariant.id is the Shopify-confirmed canonical GID.
const lookupGid = `gid://shopify/ProductVariant/${variantIdStr}`;
const variantData = await shopify.graphql<ProductVariantQueryResult>(
  `query CheckVariant($id: ID!) {
     productVariant(id: $id) {
       id
       availableForSale
       inventoryQuantity
     }
   }`,
  { id: lookupGid },
);

// Use the confirmed GID from the Shopify response (not the reconstructed one)
const confirmedVariantGid = variantData.productVariant?.id ?? lookupGid;
console.log({ batchId, confirmedVariantGid, availableForSale: variantData.productVariant?.availableForSale }, "variant availability confirmed");

